  const oauthOutcomes = await promptOAuthFlows(needsOAuth, log, {
    skipPrompt: options.yes || isNonInteractive
  });
  const allAuthorized = oauthOutcomes.size > 0 && [...oauthOutcomes.values()].every((s) => s === "ACTIVE");
